mapper.select:
SELECT /* SQL-ID : isry.itgcms.sysmgmt.userauth.mapper.UserInstAuthMapper.searchLwprtInstList : 하위기관 목록 조회 */ T.INST_NO AS INST_NO FROM ( SELECT INST_NO /* 기관번호 */ , INST_NM /* 기관명 */ , UP_INST_NO /* 상위기관번호 */ , UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , INST_TYPE_SE_CD /* 기관유형구분코드 */ , LEVEL AS LEV /* 레벨 */ FROM SAA000 /** 통합기관 */ START WITH INST_NO = #{srchUpInstNo} /* 검색할 상위기관번호 */ CONNECT BY PRIOR INST_NO = UP_INST_NO
AND (UNT_TASKWK_SE_CD = 'U01' OR UNT_TASKWK_SE_CD = #{srchUntTaskwkSeCd})
) T WHERE T.UNT_TASKWK_SE_CD = #{srchUntTaskwkSeCd} UNION SELECT TO_NUMBER(#{srchUpInstNo}) AS INST_NO FROM DUAL

mapper.update:
/* SQL-ID : isry.itgcms.sysmgmt.userauth.mapper.UserInstAuthMapper.updateUserInstAuthByReset : 사용자별 기관 권한 초기화 */ UPDATE SAB230 /** 사용자별 기관 권한 */
SYS_MNGR_YN = 'N' /* 시스템관리자여부 */ , AUTHRT_SE_CD = SUBSTR(GROUP_AUTHRT_SE_CD,1,1)||'40'||SUBSTR(AUTHRT_SE_CD,4,2)||'00' /* 권한구분코드 */ , GROUP_AUTHRT_SE_CD = SUBSTR(GROUP_AUTHRT_SE_CD,1,1)||'40' /* 그룹권한구분코드 */ , LAST_MDFR_ID = #{mdfrId} /* 최종수정자아이디 */ , LAST_MDFCN_DT = SYSDATE /* 최종수정일시 */
WHERE USER_ID = #{userId}
